#pragma once
// Meshes generated by `uv run tools/generate_fixtures.py` (never committed;
// src/kutta/fv/VERIFICATION.md, "Generated fixtures"). They live under
// $KUTTA_RUNS, else <checkout>/runs, so a worktree can use another checkout's.
#include <cstdlib>
#include <filesystem>
#include <fstream>
#include <map>
#include <sstream>
#include <string>

#include <doctest/doctest.h>

#include "kutta/core/sha256.hpp"
#include "kutta/core/types.hpp"

inline std::filesystem::path generated_fixtures() {
  if (const auto* root = std::getenv("KUTTA_RUNS")) return root;
  return KUTTA_SOURCE_DIR "/runs";
}

// The ledger's SHA-256 per fixture path, relative to the runs root.
inline std::map<std::string, std::string> generated_fixture_ledger() {
  std::ifstream in(KUTTA_SOURCE_DIR "/validation/generated_fixtures.tsv");
  KUTTA_REQUIRE(in, "missing validation/generated_fixtures.tsv");
  std::string line;
  std::getline(in, line);
  KUTTA_REQUIRE(line == "path\tbytes\tsha256", "invalid generated_fixtures.tsv header");
  std::map<std::string, std::string> ledger;
  while (std::getline(in, line)) {
    std::istringstream row(line);
    std::string path, bytes, sha;
    KUTTA_REQUIRE(std::getline(row, path, '\t') && std::getline(row, bytes, '\t') && std::getline(row, sha) && sha.size() == 64,
                  "invalid generated_fixtures.tsv row: " + line);
    ledger[path] = sha;
  }
  return ledger;
}

// The fixture's path, or empty when it is missing (the test skips, saying how
// to generate it). A file that differs from the ledger fails: it is not the
// mesh the gates were measured on.
inline std::filesystem::path generated_fixture(const std::string& relative) {
  const auto ledger = generated_fixture_ledger();
  const auto expected = ledger.find(relative);
  KUTTA_REQUIRE(expected != ledger.end(), relative + " is not in validation/generated_fixtures.tsv");
  const auto path = generated_fixtures() / relative;
  if (!std::filesystem::exists(path)) {
    MESSAGE("skipping: missing " << path.string() << " (uv run tools/generate_fixtures.py --runs "
                                 << generated_fixtures().string() << ")");
    return {};
  }
  // The context names the fixture, not the root, so the assertion has one
  // identity in every checkout (tools/forensics/compare_slow_assertions.py).
  const auto found = kutta::sha256_file(path);
  CHECK_MESSAGE(found == expected->second, relative << " matches validation/generated_fixtures.tsv");
  if (found == expected->second) return path;
  MESSAGE("skipping: " << path.string() << " is not the recorded mesh; regenerate it with uv run tools/generate_fixtures.py --force");
  return {};
}
